// One shared instrument, moved into the lesson room and returned on exit.
let roomItem=null,roomKey='',roomPlaying=false,viewMode='waterfall',fallFrame=0,fallPhase=0,fallLast=0,fallIndex=-1,returnFocus=null;
const panel=$('.piano-panel'),anchor=document.createComment('instrument-home');panel.before(anchor);
const room=document.createElement('section');room.id='lesson-room';room.hidden=true;room.setAttribute('aria-label','沉浸式课程');
room.innerHTML=`<div class="room-atmosphere"><div class="moon-window"></div><div class="horizon"></div></div><div class="room-shell"><div class="room-top"><button id="leave-room">← 返回学习空间</button><span>琴始 <i>/</i> THE LISTENING ROOM</span><button id="room-fullscreen">⛶ 全屏</button></div><div class="room-heading"><div><small id="room-kicker"></small><h1 id="room-title"></h1><p id="room-deck"></p></div><div class="room-quote">让世界安静一点，<br>让一个音符被听见。</div></div><div class="room-tabs" role="tablist" aria-label="课程章节"><button role="tab" data-chapter="story" class="active">01　走进旋律</button><button role="tab" data-chapter="listen">02　聆听与观看</button><button role="tab" data-chapter="play">03　轮到你了</button></div><div id="chapter-story" class="room-chapter"><div class="story-copy"><small id="story-label"></small><h2 id="story-title"></h2><p id="story-text"></p><a id="story-source" target="_blank" rel="noopener"></a><button class="room-primary" id="to-listen">先听听这段旋律　→</button></div><div class="story-scene"><span id="scene-word"></span><div class="scene-staff">𝄞 <span>♪　♩　♫</span></div><p id="scene-caption"></p></div></div><div id="chapter-listen" class="room-chapter" hidden><div class="listening-copy"><small>LISTEN BEFORE YOU PLAY</small><h2>先把旋律，放进心里。</h2><p id="listen-tip"></p><button id="room-demo" class="room-primary">▷ 播放教学示范</button><p class="recording-label">浏览器合成 · 简化片段 · 非真人演奏</p><div id="reference-player"></div><button id="to-play" class="room-link">听过了，开始跟弹 →</button></div><div class="listening-orb"><span>♫</span><p id="listening-status">闭上眼睛，听音符之间的距离。</p></div></div><div id="chapter-play" class="room-chapter" hidden><div class="play-intro"><div><small>YOUR TURN</small><h2 id="play-title">让音符，落在你的指尖。</h2><p id="play-guidance">音符落到亮线时按键；等待模式会等你弹对，再继续。</p></div><div class="view-switch" role="group" aria-label="曲谱视图"><button data-view="waterfall" class="active">▥ 瀑布流</button><button data-view="score">♫ 简谱</button></div></div><div id="room-instrument"></div><div class="room-session-controls"><button class="room-primary" id="room-play">▷ 开始跟弹</button><button id="room-reset">↻ 从头再来</button><label>速度 <select id="room-speed"><option value="50">慢速 · 50 BPM</option><option value="65" selected>舒缓 · 65 BPM</option><option value="80">标准 · 80 BPM</option><option value="100">轻快 · 100 BPM</option></select></label><span id="room-progress">准备好以后再开始</span></div><div id="room-result" hidden><small>A MOMENT TO REMEMBER</small><h2>这段旋律，现在也有你的声音了。</h2><p id="result-detail"></p><button id="room-next" class="room-primary">走进下一课 →</button></div></div><div class="room-foot"><span id="room-foot-title">一间只属于你的琴房</span><span>戴上耳机，给自己一点时间。</span></div></div>`;
document.body.append(room);
const fall=document.createElement('div');fall.id='waterfall';fall.innerHTML='<div class="fall-lanes"></div><div class="fall-notes"></div><div class="strike-line"><span>在这里，让声音发生</span></div>';$('#keyboard').parentElement.before(fall);for(let i=0;i<12;i++){const lane=document.createElement('div');lane.className='fall-lane';$('.fall-lanes').append(lane)}
const exerciseScenes=[['初见 · 三个音的房间','想象你推开一扇窗。房间很安静，桌上只有一束光。今天不用弹一首歌，只需要用三个音，回应这份安静。','Do、Re、Mi，是今天的全部。','FIRST LIGHT'],['漫步 · 五步的小径','把五个相邻的音想成五块石头。不用赶路，从第一块走到第五块，再慢慢走回来。每次落脚，都一样轻。','听上行与下行，感受旋律的方向。','A SMALL WALK'],['脉搏 · 音乐开始呼吸','如果音符是脚步，节拍就是一路陪着你的心跳。先不急着出发，听四次脉搏，再把自己的声音放进去。','听四拍预备，每拍弹一个音。','INNER PULSE'],['远行 · 另一个 Do','从一个 Do 出发，向更明亮的地方走。越过七个音，你会再次遇见 Do。它更高了，却依然熟悉。','倾听同名音之间，一个八度的距离。','OPEN HORIZON'],['飞跃 · 留白的距离','这次，我们不踩每一级台阶。越过一个音，让旋律轻轻跳起来。音与音之间的留白，也能成为音乐。','先看目标键，再听音程的变化。','A LITTLE LEAP']];
const songScenes=[['一颗星，为什么能变成十二种模样？','你熟悉的《小星星》旋律，与法国歌曲《啊，妈妈，我要告诉你》共享曲调。莫扎特以这支曲调写下十二首钢琴变奏。今天先弹最简单的主题，听熟悉的旋律怎样由重复和回应组成。','想象一问一答：前半句抬头，后半句回家。','STARRY NIGHT','https://kv.mozarteum.at/de/work/zwolf-variationen-in-c-uber-4057','莫扎特基金会 · 作品目录'],['从一段旋律，到众人的歌声','1824 年，贝多芬的第九交响曲在维也纳首演。终乐章将席勒《欢乐颂》的诗句唱进交响曲。你将弹奏其中主题的简化片段：很小的几个音，也能承载走向彼此的力量。','听最初几个相邻音，如何一步一步走向明亮。','TOGETHER','https://www.loc.gov/resource/gdcwdl.wdl_15063/?sp=2&st=gallery','美国国会图书馆 · 第九交响曲'],['熟悉的声音，会带你回家','先把这段旋律当作一个小小的对话：有的音重复，有的音回答。跟着音符的方向走，让每次重复都更从容。','找出重复的音，再听旋律怎样回到起点。','FAMILIAR VOICES']];
function metadata(item,key){if(key.startsWith('e')){const d=exerciseScenes[+key.slice(1)];return {title:d[0],text:d[1],listen:d[2],word:d[3],label:'课前想象 · 为这节练习创作的场景'}}const d=songScenes[item.id<2?item.id:2];return {title:item.id<2?d[0]:item.name+' · 让熟悉的旋律慢下来',text:d[1],listen:d[2],word:d[3],url:d[4],source:d[5],label:item.id<2?'作品的故事':'聆听引导 · 练习情境'}}
function start(item,key){returnFocus=document.activeElement;stopDemo();stopMetro();allOff();roomItem=item;roomKey=key;roomPlaying=false;training=null;index=0;room.hidden=false;document.body.classList.add('immersed');$('#room-instrument').append(panel);$('#room-kicker').textContent=key.startsWith('e')?`FOUNDATIONS / LESSON ${String(+key.slice(1)+1).padStart(2,'0')}`:`MELODY COLLECTION / ${item.level}`;$('#room-title').textContent=item.name;$('#room-deck').textContent=item.desc||item.author+' · 单手简化旋律';const meta=metadata(item,key);$('#story-label').textContent=meta.label;$('#story-title').textContent=meta.title;$('#story-text').textContent=meta.text;$('#scene-word').textContent=meta.word;$('#scene-caption').textContent=meta.listen;$('#listen-tip').textContent=meta.listen;$('#story-source').hidden=!meta.url;if(meta.url){$('#story-source').href=meta.url;$('#story-source').textContent='阅读来源：'+meta.source+' ↗'}$('#reference-player').innerHTML=key==='s1'?`<details><summary>观看参考演奏 · 柏林爱乐 / 拉特尔 ↗</summary><p>同作品欣赏：第九交响曲第三乐章片段，非本课《欢乐颂》主题，也非作曲家本人演奏。</p><button id="load-video">加载演奏视频</button><div id="video-host"></div><a href="https://www.youtube.com/watch?v=5TEAJy2cWrM" target="_blank" rel="noopener">如无法播放，在 YouTube 观看 ↗</a></details>`:'<p class="recording-label">本课暂未收录经核实的真人演奏视频，可先观看上方教学示范。</p>';if($('#load-video'))$('#load-video').onclick=()=>{stopDemo();$('#video-host').innerHTML='<iframe title="柏林爱乐：贝多芬第九交响曲第三乐章，拉特尔指挥" src="https://www.youtube-nocookie.com/embed/5TEAJy2cWrM" allow="fullscreen; encrypted-media; picture-in-picture" allowfullscreen></iframe>';$('#load-video').hidden=true};$('#room-result').hidden=true;$('#room-play').textContent='▷ 开始跟弹';$('#room-progress').textContent='准备好以后再开始';$('#bpm').value=$('#room-speed').value;chapter('story');$('#leave-room').focus();}
function chapter(name){stopDemo();stopMetro();allOff();roomPlaying=false;cancelAnimationFrame(fallFrame);$$('.room-chapter').forEach(x=>x.hidden=x.id!=='chapter-'+name);$$('[data-chapter]').forEach(x=>{x.classList.toggle('active',x.dataset.chapter===name);x.setAttribute('aria-selected',x.dataset.chapter===name?'true':'false')});$('#video-host')?.replaceChildren();$('#load-video')?.removeAttribute('hidden');if(name==='play'){runLesson(roomItem,roomKey);stopMetro();roomPlaying=false;$('#room-play').textContent='▷ 开始跟弹';$('#feedback').textContent='准备好后点击“开始跟弹”';setView(viewMode);refreshFalls()}$('#listening-status').textContent='闭上眼睛，听音符之间的距离。';$('#room-demo').textContent='▷ 播放教学示范'}
function setView(v){viewMode=v;room.dataset.view=v;$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-pressed',b.dataset.view===v?'true':'false')});if(v==='waterfall')refreshFalls()}
function beginRoom(){if(roomPlaying){roomPlaying=false;stopDemo();stopMetro();allOff();$('#room-play').textContent='▷ 继续跟弹';cancelAnimationFrame(fallFrame);return}stopDemo();roomPlaying=true;if(!training||index===training.notes.length)runLesson(roomItem,roomKey);else if(training.rhythm){startMetro();rhythmStart=performance.now()+4*60000/lockedBpm}$('#room-play').textContent='Ⅱ 暂停';$('#feedback').textContent=training.rhythm?'预备四拍，跟着节拍弹奏':'等音模式：弹对一个音，旋律再向前一步';fallLast=performance.now();animateFalls(fallLast)}
function refreshFalls(){if(room.hidden||!roomItem)return;let seq=training?.notes||roomItem.notes;let active=training?index:0;if(fallIndex!==active){fallIndex=active;fallPhase=0}$('.fall-notes').innerHTML=seq.slice(active,active+8).map((m,i)=>{const k=whites.indexOf(m);return `<div class="fall-note ${i===0?'next-note':''}" style="left:calc(${(k+.5)/12*100}% - 2.7%);bottom:${i*62+8}px"><b>${Object.keys(keys).find(k=>keys[k]===m)?.toUpperCase()}</b><small>${names[k]}</small></div>`}).join('');$('#room-progress').textContent=`${active} / ${seq.length} 音符${training&&attempts?' · '+Math.round(correct/attempts*100)+'% 准确':''}`;if(roomPlaying){const n=$('.fall-note.next-note');if(n)n.style.bottom='8px'}}
function animateFalls(now){cancelAnimationFrame(fallFrame);if(!roomPlaying||room.hidden)return;const delta=Math.min(80,now-fallLast);fallLast=now;fallPhase=Math.min(1,fallPhase+delta/(60000/bpm()));$$('.fall-note').forEach((n,i)=>n.style.bottom=(Math.max(0,i*62+62-fallPhase*62)+8)+'px');fallFrame=requestAnimationFrame(animateFalls)}
function completeRoom(){if(room.hidden)return;roomPlaying=false;cancelAnimationFrame(fallFrame);$('#room-result').hidden=false;$('#result-detail').textContent=`完成 ${roomItem.notes.length} 个音符 · 准确率 ${Math.round(correct/attempts*100)}%。先记住这次声音，再继续下一段旅程。`;$('#room-play').textContent='▷ 再弹一遍';$('#room-next').textContent=roomKey==='s11'?'回到曲库 →':'走进下一课 →'}
function leaveRoom(){exit();roomPlaying=false;cancelAnimationFrame(fallFrame);room.hidden=true;document.body.classList.remove('immersed');anchor.after(panel);$('#video-host')?.replaceChildren();if(document.fullscreenElement)document.exitFullscreen?.();returnFocus?.focus()}
$('#leave-room').onclick=leaveRoom;$('#to-listen').onclick=()=>chapter('listen');$('#to-play').onclick=()=>chapter('play');$$('[data-chapter]').forEach(b=>b.onclick=()=>chapter(b.dataset.chapter));$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#room-play').onclick=beginRoom;$('#room-reset').onclick=()=>{roomPlaying=false;runLesson(roomItem,roomKey);stopMetro();$('#room-result').hidden=true;$('#room-play').textContent='▷ 开始跟弹';$('#feedback').textContent='已回到起点，准备好再开始';refreshFalls()};$('#room-speed').onchange=()=>{$('#bpm').value=$('#room-speed').value;if(roomPlaying&&training?.rhythm){runLesson(roomItem,roomKey)}fallPhase=0};$('#room-demo').onclick=()=>{if(demoing){stopDemo();$('#room-demo').textContent='▷ 播放教学示范';$('#listening-status').textContent='已暂停，随时可以重新听。';return}training={...roomItem,key:roomKey,rhythm:false};index=0;$('#demo').click();$('#room-demo').textContent='■ 停止示范';$('#listening-status').textContent='正在示范：'+roomItem.name;const end=setTimeout(()=>{$('#room-demo').textContent='▷ 再听一遍';$('#listening-status').textContent='现在，把这段旋律交给你。'},roomItem.notes.length*60000/bpm()+50);demoTimers.push(end)};$('#room-next').onclick=()=>{const e=roomKey.startsWith('e'),n=+roomKey.slice(1)+1,list=e?exercises:songs;if(n<list.length)start(list[n],(e?'e':'s')+n);else{leaveRoom();page('library')}};$('#room-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await room.requestFullscreen()}catch{toast('当前浏览器暂不支持全屏，沉浸琴房仍可正常使用')}};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!room.hidden&&!$('#help-dialog').open)leaveRoom()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&roomPlaying){roomPlaying=false;cancelAnimationFrame(fallFrame);$('#room-play').textContent='▷ 继续跟弹'}});
$('#exit-training').onclick=leaveRoom;$('#restart').onclick=()=>$('#room-reset').click();

const basePress=press;press=function(m,source){basePress(m,source);if(demoing&&!room.hidden&&!$('#chapter-listen').hidden){$('.listening-orb>span').textContent=solfege[whites.indexOf(m)]||'♪';$('#listening-status').textContent=`${names[whites.indexOf(m)]} · 按键 ${Object.keys(keys).find(k=>keys[k]===m)?.toUpperCase()}`}};
